/**
 * Workers' comp case forms browser test: a company uploads its own paper forms, then a case manager fills,
 * signs, prints, downloads, emails and voids them. A coordinator without medical access never reaches the HIPAA form.
 *
 * The forms used here are synthetic PDFs generated by the test; no company's real forms are in the repository.
 * Email goes to the capture adapter: start the server and run the test with the same FORGE_EMAIL_CAPTURE_DIR
 * (and no RESEND_API_KEY).
 *
 * Run: pnpm exec playwright test apps/web/tests/port-s2-wc-forms.spec.cjs --reporter=line --workers=1
 */
const fs = require('fs')
const path = require('path')
const crypto = require('crypto')
const { test, expect } = require('@playwright/test')
const { PDFDocument, StandardFonts } = require('pdf-lib')

const envPath = path.join(__dirname, '../.env.local')
if (fs.existsSync(envPath)) {
  for (const line of fs.readFileSync(envPath, 'utf8').split(/\r?\n/)) {
    const match = line.match(/^([A-Z0-9_]+)=(.*)$/)
    if (match && !process.env[match[1]]) process.env[match[1]] = match[2]
  }
}

const baseURL = process.env.SMOKE_BASE_URL || 'http://127.0.0.1:3000'
const API_URL = process.env.API_URL || process.env.NEXT_PUBLIC_SUPABASE_URL
const SERVICE_ROLE_KEY = process.env.SERVICE_ROLE_KEY || process.env.SUPABASE_SERVICE_ROLE_KEY
const CAPTURE_DIR = process.env.FORGE_EMAIL_CAPTURE_DIR
const ORG_A = '20000000-0000-4000-8000-000000000100'
const ADMIN_USER = '20000000-0000-4000-8000-000000000001'
const DEMO_USER = '20000000-0000-4000-8000-000000000002'
const RUN = Date.now().toString().slice(-6)

test.describe.configure({ mode: 'serial' })
test.setTimeout(240000)

const rest = async (pathname, { method = 'GET', body } = {}) => {
  const response = await fetch(API_URL + pathname, {
    method,
    headers: { apikey: SERVICE_ROLE_KEY, Authorization: 'Bearer ' + SERVICE_ROLE_KEY, 'Content-Type': 'application/json', Prefer: 'return=representation' },
    body: body ? JSON.stringify(body) : undefined
  })
  const text = await response.text()
  if (!response.ok) throw new Error(`${method} ${pathname} failed: ${text}`)
  return text ? JSON.parse(text) : null
}

async function login(page, email) {
  await page.goto(baseURL + '/auth/login')
  await page.locator('input[name="email"]').fill(email)
  await page.locator('input[name="password"]').fill('ForgeDev2!')
  await page.getByRole('button', { name: /Sign in to Forge Industrial Safety 2\.0/i }).click()
  await page.waitForURL(url => !url.pathname.startsWith('/auth/login'), { timeout: 30000 })
}

const open = async (page, url) => {
  await page.goto(url.startsWith('http') ? url : baseURL + url)
  await page.waitForLoadState('networkidle')
}

// One-page synthetic company forms with labelled blanks.
const syntheticForm = async title => {
  const document = await PDFDocument.create()
  const page = document.addPage([612, 792])
  const font = await document.embedFont(StandardFonts.Helvetica)
  page.drawText(`Sample Company ${RUN}`, { x: 72, y: 740, size: 14, font })
  page.drawText(title, { x: 72, y: 715, size: 18, font })
  page.drawText('Synthetic test form - not a real company document.', { x: 72, y: 60, size: 9, font })
  return Buffer.from(await document.save())
}

const drawSignature = async page => {
  const pad = page.getByTestId('signature-pad')
  await pad.scrollIntoViewIfNeeded()
  const box = await pad.boundingBox()
  await page.mouse.move(box.x + 30, box.y + box.height * 0.6)
  await page.mouse.down()
  for (let step = 1; step <= 20; step += 1) {
    await page.mouse.move(box.x + 30 + step * 12, box.y + box.height * (0.6 - 0.25 * Math.sin(step / 2)))
  }
  await page.mouse.up()
}

const sha = bytes => crypto.createHash('sha256').update(bytes).digest('hex')

let fx = null

test.beforeAll(async () => {
  expect(CAPTURE_DIR, 'set FORGE_EMAIL_CAPTURE_DIR for the server and this test').toBeTruthy()

  const [location] = await rest('/rest/v1/locations', { method: 'POST', body: { organization_id: ORG_A, name: `WC Forms Plant ${RUN}`, code: `WF${RUN}` } })
  const [employee] = await rest('/rest/v1/forge_personnel', {
    method: 'POST',
    body: { organization_id: ORG_A, first_name: 'Riley', last_name: `Forms ${RUN}`, employment_status: 'active', location_id: location.id, created_by: ADMIN_USER, updated_by: ADMIN_USER }
  })
  const [staff] = await rest('/rest/v1/forge_personnel', {
    method: 'POST',
    body: { organization_id: ORG_A, first_name: 'Safety', last_name: `Lead ${RUN}`, email: `safety-lead-${RUN}@example.com`, employment_status: 'active', location_id: location.id, created_by: ADMIN_USER, updated_by: ADMIN_USER }
  })
  await rest('/rest/v1/forge_personnel_sensitive', { method: 'POST', body: { organization_id: ORG_A, personnel_id: employee.id, date_of_birth: '1985-03-09' } })

  const caseNumber = await rest('/rest/v1/rpc/next_forge_wc_case_number', { method: 'POST', body: { p_organization_id: ORG_A, p_year: 2026 } })
  const [wc] = await rest('/rest/v1/forge_wc_cases', {
    method: 'POST',
    body: {
      organization_id: ORG_A, case_number: caseNumber, personnel_id: employee.id, employee_name: `Riley Forms ${RUN}`, location_id: location.id,
      injury_date: '2026-10-01', reported_date: '2026-10-01', stage: 'treatment', created_by: ADMIN_USER, updated_by: ADMIN_USER
    }
  })

  // A coordinator who can view and edit workers' comp, but has no medical access.
  const [role] = await rest('/rest/v1/forge_tenant_roles', {
    method: 'POST',
    body: { organization_id: ORG_A, role_key: `port-wcf-${RUN}`, name: `WC Forms Coordinator ${RUN}`, is_system_role: false, is_active: true, sort_order: 905 }
  })
  const permissions = await rest('/rest/v1/forge_permission_registry?select=id&permission_key=in.(workers_comp.view,workers_comp.edit)')
  await rest('/rest/v1/forge_tenant_role_permissions', { method: 'POST', body: permissions.map(item => ({ role_id: role.id, permission_id: item.id, allowed: true, scope: 'organization' })) })
  await rest('/rest/v1/forge_tenant_user_roles', { method: 'POST', body: { organization_id: ORG_A, user_id: DEMO_USER, role_id: role.id } })

  fx = {
    wc, staff, role,
    caseUrl: `${baseURL}/workers-comp/${wc.id}`,
    hipaaPdf: await syntheticForm('HIPAA Authorization Form'),
    guidelinesPdf: await syntheticForm('Employee Injury Guidelines')
  }
})

test.afterAll(async () => {
  if (fx?.role) await rest(`/rest/v1/forge_tenant_roles?id=eq.${fx.role.id}`, { method: 'DELETE' })
})

test('company forms are uploaded in settings and the blank prints byte for byte', async ({ page }) => {
  await login(page, 'admin@forge2.local')
  await open(page, '/workers-comp/settings')

  const hipaa = page.getByTestId('wc-form-template-hipaa_authorization')
  await hipaa.getByLabel('HIPAA Authorization PDF').setInputFiles({ name: `hipaa-${RUN}.pdf`, mimeType: 'application/pdf', buffer: fx.hipaaPdf })
  await hipaa.getByRole('button', { name: /Upload|Replace/ }).click()
  await expect(hipaa).toContainText(`hipaa-${RUN}.pdf`, { timeout: 30000 })

  const guidelines = page.getByTestId('wc-form-template-injury_guidelines_ack')
  await guidelines.getByLabel('Employee Injury Guidelines PDF').setInputFiles({ name: 'not-a-pdf.pdf', mimeType: 'application/pdf', buffer: Buffer.from('hello') })
  await guidelines.getByRole('button', { name: /Upload|Replace/ }).click()
  await expect(page.getByText('The file must be a PDF.')).toBeVisible({ timeout: 30000 })
  await guidelines.getByLabel('Employee Injury Guidelines PDF').setInputFiles({ name: `guidelines-${RUN}.pdf`, mimeType: 'application/pdf', buffer: fx.guidelinesPdf })
  await guidelines.getByRole('button', { name: /Upload|Replace/ }).click()
  await expect(guidelines).toContainText(`guidelines-${RUN}.pdf`, { timeout: 30000 })

  const [template] = await rest(`/rest/v1/forge_wc_form_templates?organization_id=eq.${ORG_A}&form_key=eq.hipaa_authorization&is_active=eq.true&select=id,sha256`)
  expect(template.sha256).toBe(sha(fx.hipaaPdf))
  const blank = await page.request.get(`${baseURL}/api/workers-comp/forms/templates/${template.id}`)
  expect(blank.headers()['content-type']).toContain('application/pdf')
  expect(sha(await blank.body())).toBe(sha(fx.hipaaPdf))
  fx.hipaaTemplateId = template.id
})

test('HIPAA authorization: fill, sign, download, email with the PDF attached, then void', async ({ page }) => {
  await login(page, 'admin@forge2.local')
  await open(page, fx.caseUrl)

  const forms = page.getByTestId('wc-forms')
  await expect(forms.getByTestId('wc-form-available-hipaa_authorization')).toBeVisible({ timeout: 30000 })
  await forms.getByRole('button', { name: 'Start HIPAA Authorization' }).click()
  await page.waitForURL(/\/workers-comp\/[^/]+\/forms\/[^/]+$/, { timeout: 30000 })
  await page.waitForLoadState('networkidle')
  const formId = page.url().split('/').pop()

  // Prefilled from the case and the personnel record (date of birth needs medical manage access).
  await expect(page.locator('#wc-form-patient_name')).toHaveValue(`Riley Forms ${RUN}`)
  await expect(page.locator('#wc-form-date_of_birth')).toHaveValue('1985-03-09')

  await page.locator('#wc-form-provider_name').fill('Example Occupational Clinic')
  for (const key of ['initial_release_records', 'initial_sensitive_info', 'initial_mail_fax']) await page.locator(`#wc-form-${key}`).fill('RF')
  await page.getByRole('button', { name: 'Save Draft' }).click()
  await expect(page.getByText('Draft saved.')).toBeVisible({ timeout: 30000 })
  await page.waitForLoadState('networkidle')

  await expect(page.getByRole('button', { name: 'Sign Form' })).toBeDisabled()
  await drawSignature(page)
  await page.getByRole('button', { name: 'Sign Form' }).click()
  await expect(page.getByTestId('wc-form-status')).toHaveText('signed', { timeout: 30000 })
  await expect(page.locator('#wc-form-provider_name')).toBeDisabled()

  const [stored] = await rest(`/rest/v1/forge_wc_case_forms?id=eq.${formId}&select=status,signer_name,signer_relationship,signature_path,field_data`)
  expect(stored).toMatchObject({ status: 'signed', signer_name: `Riley Forms ${RUN}`, signer_relationship: 'Self' })
  expect(stored.field_data.initial_unencrypted_email).toBeUndefined()

  // The filled PDF: the company's page with the overlay.
  const download = await page.request.get(`${baseURL}/api/workers-comp/forms/${formId}/pdf?download=1`)
  expect(download.headers()['content-type']).toContain('application/pdf')
  expect(download.headers()['content-disposition']).toContain('attachment')
  const filled = await download.body()
  const document = await PDFDocument.load(filled)
  expect(document.getPageCount()).toBe(1)
  expect(sha(filled)).not.toBe(sha(fx.hipaaPdf))
  expect(filled.toString('latin1')).toMatch(/\/Subtype\s*\/Image/)

  // Email to a staff member from personnel and an outside address, with the filled PDF attached.
  const before = new Set(fs.existsSync(CAPTURE_DIR) ? fs.readdirSync(CAPTURE_DIR) : [])
  const email = page.getByTestId('wc-form-email')
  await email.getByLabel('Staff').fill(`Lead ${RUN}`)
  await page.getByTestId('wc-form-staff').getByRole('checkbox', { name: `Safety Lead ${RUN}` }).check()
  await email.getByLabel('Outside addresses').fill(`adjuster-${RUN}@example.com, not-an-address`)
  await email.getByRole('button', { name: 'Send Email' }).click()
  await expect(page.getByText('Not a valid email address: not-an-address')).toBeVisible({ timeout: 30000 })
  await email.getByLabel('Outside addresses').fill(`adjuster-${RUN}@example.com`)
  await email.getByLabel('Note').fill('Signed authorization for the claim file.')
  await email.getByRole('button', { name: 'Send Email' }).click()
  await expect(page.getByText('Emailed to 2 recipients.')).toBeVisible({ timeout: 30000 })

  const sent = fs.readdirSync(CAPTURE_DIR).filter(name => !before.has(name)).map(name => JSON.parse(fs.readFileSync(path.join(CAPTURE_DIR, name), 'utf8')))
  expect(sent.map(item => item.to).sort()).toEqual([`adjuster-${RUN}@example.com`, `safety-lead-${RUN}@example.com`].sort())
  for (const message of sent) {
    expect(message.subject).toContain(`HIPAA Authorization for workers' comp case ${fx.wc.case_number}`)
    expect(message.text).toContain('Signed authorization for the claim file.')
    expect(message.text).toContain('protected health information')
    expect(message.attachments).toHaveLength(1)
    expect(message.attachments[0].filename).toBe(`${fx.wc.case_number} HIPAA Authorization.pdf`)
    expect(Buffer.from(message.attachments[0].content, 'base64').subarray(0, 5).toString('latin1')).toBe('%PDF-')
  }

  await open(page, `${fx.caseUrl}/forms/${formId}`)
  const history = page.getByTestId('wc-form-history')
  await expect(history).toContainText('Emailed')
  await expect(history).toContainText(`adjuster-${RUN}@example.com`)
  await expect(history).toContainText('Downloaded')
  await expect(history).toContainText('Signed')

  // Corrections: void with a reason; the signed copy stays on record.
  await page.locator('#wc-form-void-reason').fill('Wrong provider listed')
  page.once('dialog', dialog => dialog.accept())
  await page.getByRole('button', { name: 'Void Form' }).click()
  await expect(page.getByTestId('wc-form-status')).toHaveText('voided', { timeout: 30000 })
  await expect(page.getByText('Voided: Wrong provider listed')).toBeVisible()
  await expect(page.getByTestId('wc-form-email')).toHaveCount(0)

  // HIPAA forms never appear in case history, which every case viewer can read.
  await open(page, fx.caseUrl)
  await expect(page.getByTestId('wc-activity')).not.toContainText('HIPAA')
  fx.hipaaFormId = formId
})

test('injury guidelines: the employee signs to acknowledge receiving them', async ({ page }) => {
  await login(page, 'admin@forge2.local')
  await open(page, fx.caseUrl)
  await page.getByTestId('wc-forms').getByRole('button', { name: 'Start Employee Injury Guidelines' }).click()
  await page.waitForURL(/\/forms\/[^/]+$/, { timeout: 30000 })
  await page.waitForLoadState('networkidle')
  await expect(page.locator('#wc-form-employee_name')).toHaveValue(`Riley Forms ${RUN}`)
  await expect(page.locator('#wc-form-signer-relationship')).toHaveCount(0)
  await drawSignature(page)
  await page.getByRole('button', { name: 'Sign Form' }).click()
  await expect(page.getByTestId('wc-form-status')).toHaveText('signed', { timeout: 30000 })

  const formId = page.url().split('/').pop()
  const printed = await page.request.get(`${baseURL}/api/workers-comp/forms/${formId}/pdf`)
  expect(printed.headers()['content-disposition']).toContain('inline')
  expect((await PDFDocument.load(await printed.body())).getPageCount()).toBe(1)

  await open(page, fx.caseUrl)
  await expect(page.getByTestId('wc-activity')).toContainText(`Employee Injury Guidelines signed by Riley Forms ${RUN}.`)
  await expect(page.getByTestId('wc-form-list')).toContainText('Employee Injury Guidelines')
  fx.guidelinesFormId = formId
})

test('a coordinator without medical access never reaches the HIPAA form', async ({ page }) => {
  await login(page, 'user@forge2.local')
  await open(page, fx.caseUrl)

  const forms = page.getByTestId('wc-forms')
  await expect(forms.getByTestId('wc-form-available-injury_guidelines_ack')).toBeVisible({ timeout: 30000 })
  await expect(forms.getByTestId('wc-form-available-hipaa_authorization')).toHaveCount(0)
  await expect(forms).not.toContainText('HIPAA')

  expect((await page.request.get(`${baseURL}/api/workers-comp/forms/${fx.hipaaFormId}/pdf`)).status()).toBe(404)
  expect((await page.request.get(`${baseURL}/api/workers-comp/forms/templates/${fx.hipaaTemplateId}`)).status()).toBe(404)
  expect((await page.request.get(`${baseURL}/api/workers-comp/forms/${fx.guidelinesFormId}/pdf`)).status()).toBe(200)

  const response = await page.goto(`${fx.caseUrl}/forms/${fx.hipaaFormId}`)
  expect(response.status()).toBe(404)

  // Template uploads need the configure permission.
  const upload = await page.request.post(`${baseURL}/api/workers-comp/forms/templates`, {
    headers: { Origin: baseURL },
    multipart: { formKey: 'hipaa_authorization', file: { name: 'x.pdf', mimeType: 'application/pdf', buffer: fx.hipaaPdf } }
  })
  expect(upload.url()).not.toContain('/api/workers-comp/forms/templates')
  const [active] = await rest(`/rest/v1/forge_wc_form_templates?organization_id=eq.${ORG_A}&form_key=eq.hipaa_authorization&is_active=eq.true&select=id`)
  expect(active.id).toBe(fx.hipaaTemplateId)
})
